package com.stillfeed.app.data.local.device

import android.content.Context
import android.content.SharedPreferences

/**
 * Storage abstraction for persisting the server-issued device restore credential.
 *
 * Security & Durability Architecture (STEP 05 Final Remediation):
 *
 * 1. Origin:
 *    This credential is NEVER generated by the client and is NEVER a client device ID (such as ANDROID_ID).
 *    It is generated and issued by the backend exclusively during trusted device enrollment.
 *
 * 2. Protection:
 *    Stored in Android Block Store (or app-private secure storage for local caching).
 *    It is never synchronized to other devices, never backed up to generic cloud accounts,
 *    and never exposed through public user profile APIs.
 *
 * 3. Role in Restore:
 *    During reinstall recovery on the SAME device, this credential proves prior enrollment.
 *    On a different device (or for an attacker knowing the device_binding_id), this credential
 *    is absent. Submitting a plain device_binding_id or client string will be rejected by the server.
 */
interface DeviceRestoreCredentialStore {
    suspend fun getRestoreCredential(): String?
    suspend fun saveRestoreCredential(credential: String)
    suspend fun clearRestoreCredential()
}

/**
 * Delegate interface for Google Play services BlockStoreClient interactions.
 * Abstracts [com.google.android.gms.auth.blockstore.BlockStoreClient] for testability
 * and clean separation of concerns.
 */
interface BlockStoreClientDelegate {
    /**
     * Stores raw bytes with the specified key and cloud-backup policy.
     *
     * Maps to:
     * StoreBytesData.Builder()
     *     .setBytes(bytes)
     *     .setKey(key)
     *     .setShouldBackupToCloud(shouldBackupToCloud)
     *     .build()
     */
    suspend fun storeBytes(key: String, bytes: ByteArray, shouldBackupToCloud: Boolean): Boolean

    /**
     * Retrieves stored bytes for the specified key.
     *
     * Maps to:
     * RetrieveBytesRequest.Builder()
     *     .setKeys(listOf(key))
     *     .build()
     */
    suspend fun retrieveBytes(key: String): ByteArray?

    /**
     * Deletes stored bytes for the specified key.
     */
    suspend fun deleteBytes(key: String): Boolean
}

/**
 * Android Block Store implementation of [DeviceRestoreCredentialStore].
 *
 * ARCHITECTURE & SECURITY SPECIFICATION:
 *
 * 1. Exact Block Store API Used:
 *    - Store: [com.google.android.gms.auth.blockstore.StoreBytesData.Builder]
 *        .setBytes(credential.toByteArray(Charsets.UTF_8))
 *        .setKey(BLOCK_STORE_RESTORE_CREDENTIAL_KEY)
 *        .setShouldBackupToCloud(false) // MANDATORY: Device-local only!
 *        .build()
 *    - Retrieve: [com.google.android.gms.auth.blockstore.RetrieveBytesRequest.Builder]
 *        .setKeys(listOf(BLOCK_STORE_RESTORE_CREDENTIAL_KEY))
 *        .build()
 *
 * 2. Why `setShouldBackupToCloud(false)` is Mandatory:
 *    - STILLFEED strictly forbids automatic cross-device history restoration.
 *    - By setting shouldBackupToCloud = false, Google Play services stores the credential
 *      exclusively on the physical device. It is NEVER uploaded to Google Drive or Google Cloud Backup.
 *    - When a user sets up a new phone (via cloud backup or cable migration), Google Play services
 *      does NOT restore this block to the new phone.
 *    - Consequently, the new device will NOT have the restore credential, blocking cross-device restoration.
 *
 * 3. Same-Device Reinstall Behavior:
 *    - Unlike app-private storage (/data/data/<package>), Google Play services Block Store
 *      retains this local data block across package uninstalls on the SAME physical device.
 *    - When STILLFEED is reinstalled on the same phone, retrieveBytes() recovers the existing
 *      server-issued credential.
 *    - The app submits this credential to the server RPC to restore history without re-enrolling.
 *
 * 4. Device-to-Device Migration Behavior:
 *    - Because shouldBackupToCloud = false, the new device does NOT receive the credential.
 *    - The new device has no restore credential and cannot restore existing history.
 *    - Re-enrollment is rejected by the server with DENIED_ALREADY_BOUND.
 *    - Existing history remains securely bound to the original physical hardware.
 *
 * 5. When Credential Cannot Be Recovered:
 *    - If the credential is lost (e.g. factory reset, Google Play services data cleared, or corrupted),
 *      [getRestoreCredential] returns null.
 *    - Restore execution is DENIED to prevent unauthorized or unverified access.
 *    - The app does NOT silently generate or enroll a new binding.
 *
 * 6. Prohibition on Ordinary SharedPreferences / Jetpack DataStore:
 *    - Ordinary SharedPreferences and Jetpack DataStore are stored in app-private directories that
 *      are completely wiped by Android upon uninstall. They CANNOT provide same-device reinstall durability.
 *    - EncryptedSharedPreferences alone is wiped on uninstall and therefore cannot survive uninstall/reinstall.
 *    - Storing this secret credential in ordinary Jetpack DataStore is strictly prohibited.
 */
class BlockStoreDeviceRestoreCredentialStore(
    private val clientDelegate: BlockStoreClientDelegate,
    private val key: String = BLOCK_STORE_RESTORE_CREDENTIAL_KEY
) : DeviceRestoreCredentialStore {

    override suspend fun getRestoreCredential(): String? {
        val bytes = clientDelegate.retrieveBytes(key) ?: return null
        return String(bytes, Charsets.UTF_8).ifBlank { null }
    }

    override suspend fun saveRestoreCredential(credential: String) {
        require(credential.isNotBlank()) { "Restore credential cannot be blank" }
        clientDelegate.storeBytes(
            key = key,
            bytes = credential.toByteArray(Charsets.UTF_8),
            shouldBackupToCloud = false // STRICTLY ENFORCED: Device-local only!
        )
    }

    override suspend fun clearRestoreCredential() {
        clientDelegate.deleteBytes(key)
    }

    companion object {
        const val BLOCK_STORE_RESTORE_CREDENTIAL_KEY = "stillfeed_sfrc_block_credential"
    }
}

/**
 * In-memory test double for [DeviceRestoreCredentialStore].
 */
class InMemoryDeviceRestoreCredentialStore(
    private var initialCredential: String? = null
) : DeviceRestoreCredentialStore {
    private var credential: String? = initialCredential

    override suspend fun getRestoreCredential(): String? = credential

    override suspend fun saveRestoreCredential(credential: String) {
        this.credential = credential
    }

    override suspend fun clearRestoreCredential() {
        this.credential = null
    }
}

/**
 * In-memory delegate simulating Google Play services Block Store behavior for unit testing.
 */
class InMemoryBlockStoreClientDelegate : BlockStoreClientDelegate {
    data class StoredBlock(
        val bytes: ByteArray,
        val shouldBackupToCloud: Boolean
    ) {
        override fun equals(other: Any?): Boolean {
            if (this === other) return true
            if (javaClass != other?.javaClass) return false
            other as StoredBlock
            return bytes.contentEquals(other.bytes) && shouldBackupToCloud == other.shouldBackupToCloud
        }

        override fun hashCode(): Int {
            var result = bytes.contentHashCode()
            result = 31 * result + shouldBackupToCloud.hashCode()
            return result
        }
    }

    val store = mutableMapOf<String, StoredBlock>()

    override suspend fun storeBytes(key: String, bytes: ByteArray, shouldBackupToCloud: Boolean): Boolean {
        store[key] = StoredBlock(bytes.clone(), shouldBackupToCloud)
        return true
    }

    override suspend fun retrieveBytes(key: String): ByteArray? {
        return store[key]?.bytes?.clone()
    }

    override suspend fun deleteBytes(key: String): Boolean {
        return store.remove(key) != null
    }

    /**
     * Simulates device-to-device migration.
     * Blocks where `shouldBackupToCloud == false` are NOT copied to the new device!
     */
    fun simulateMigrationToNewDevice(): InMemoryBlockStoreClientDelegate {
        val newDeviceDelegate = InMemoryBlockStoreClientDelegate()
        store.forEach { (key, block) ->
            if (block.shouldBackupToCloud) {
                newDeviceDelegate.store[key] = block
            }
        }
        return newDeviceDelegate
    }
}

/**
 * Android implementation of [DeviceRestoreCredentialStore] using app-private SharedPreferences
 * for sandbox local caching.
 *
 * NOTE: App-private SharedPreferences data is deleted upon app uninstallation by the OS.
 * Reinstall durability across uninstall/reinstall requires [BlockStoreDeviceRestoreCredentialStore].
 */
class SecurePreferencesDeviceRestoreCredentialStore(
    context: Context,
    prefsName: String = PREFS_NAME
) : DeviceRestoreCredentialStore {

    private val sharedPreferences: SharedPreferences =
        context.getSharedPreferences(prefsName, Context.MODE_PRIVATE)

    override suspend fun getRestoreCredential(): String? {
        return sharedPreferences.getString(KEY_RESTORE_CREDENTIAL, null)
    }

    override suspend fun saveRestoreCredential(credential: String) {
        sharedPreferences.edit()
            .putString(KEY_RESTORE_CREDENTIAL, credential)
            .apply()
    }

    override suspend fun clearRestoreCredential() {
        sharedPreferences.edit()
            .remove(KEY_RESTORE_CREDENTIAL)
            .apply()
    }

    companion object {
        const val PREFS_NAME = "stillfeed_device_restore_credentials"
        private const val KEY_RESTORE_CREDENTIAL = "server_issued_restore_credential"
    }
}
